<script setup>
import { computed, ref, nextTick } from 'vue'
import HelpTip from './HelpTip.vue'
import OptimizerCurveInput from './OptimizerCurveInput.vue'
const props=defineProps({config:{type:Object,required:true},providers:Array,forecast:Object,error:String,busy:Boolean,editing:Boolean})
const emit=defineEmits(['save','cancel'])
const section=ref('scenario')
const today=new Intl.DateTimeFormat('en-CA').format(new Date())
function datesChanged(){if(configValue().market_mode!=='historical')return;const c=configValue(),start=new Date(c.start_date+'T12:00:00'),end=new Date(c.end_date+'T12:00:00');if(!Number.isNaN(start.getTime())&&!Number.isNaN(end.getTime()))c.horizon_months=Math.max(1,(end.getFullYear()-start.getFullYear())*12+end.getMonth()-start.getMonth()+Number(end.getDate()>start.getDate()))}
function configValue(){return props.config}
function spotChanged(product,ticker,value){product.spot_overrides ||= {};if(value==='')delete product.spot_overrides[ticker];else product.spot_overrides[ticker]=Number(value)}
const validationError=ref('')
function showInvalid(event){
  if(validationError.value)return
  const field=event.target
  const panel=field.closest('[data-config-section]')
  if(panel)section.value=panel.dataset.configSection
  const label=field.getAttribute('aria-label')||field.labels?.[0]?.textContent?.trim()||'le champ indiqué'
  validationError.value=`Vérifiez « ${label} » : ${field.validationMessage}`
  nextTick(()=>{const details=field.closest('details');if(details)details.open=true;field.focus()})
}
const names={hector:'Kepler Cheuvreux Solutions',leonteq:'Leonteq',bnp:'BNP Paribas',sg:'Société Générale',ca:'Citi',ubs:'UBS'}
const labels={reverse_convertible:'Reverse Convertible',phoenix:'Phoenix',autocall_athena:'Athena classique'}
const coverageNames={clients:'Clients et contacts',products:'Product, scripts et catalogue',pricing:'Pricer',rfq:'RFQ envoyées/reçues',booking:'Booking et règlements',lifecycle:'Constatations et flux',risk:'Greeks, stress et concentrations',ccr:'CCR et cadre juridique',documents:'KID et EMT',valuations:'Historique et Valo Explain',reinvestment:'Réinvestissement',optimizer:'Product Optimizer et recherches',administration:'Administration',screens:'Contrôles visuels'}
const models=computed(()=>props.providers?.find(p=>p.key===props.config.provider)?.models||[])
const active=computed(()=>props.config.participants.filter(p=>p.active))
const requesters=computed(()=>active.value.filter(p=>p.request_rfq))
const responders=computed(()=>active.value.filter(p=>p.respond_rfq&&p.issue_notes))
const rows=computed(()=>Array.from({length:Math.max(props.config.horizon_months,...props.config.calendar.filter(r=>r.count).map(r=>r.month))},(_,i)=>props.config.calendar.find(r=>r.month===i+1)||{month:i+1,count:0,slots:[]}))
function count(row,value){let target=props.config.calendar.find(r=>r.month===row.month);if(!target){target={...row};props.config.calendar.push(target)}target.count=Number(value);target.slots=target.slots.slice(0,target.count)}
function slot(row,index){let target=props.config.calendar.find(r=>r.month===row.month);while(target.slots.length<=index)target.slots.push({requester:null,template:null,recipients:[]});return target.slots[index]}
function roleChange(p){if(p.respond_rfq)p.issue_notes=true}
function override(p){p.economy=p.economy?null:JSON.parse(JSON.stringify(props.config.economy_common))}
function addFunding(e){const last=e.funding.at(-1);e.funding.push({month:last.month+3,pillars:last.pillars.map(n=>[...n])})}
function addProduct(code){if(!props.config.products.some(p=>p.template===code))props.config.products.push({template:code,nominal:10000000,maturity_months:code==='autocall_athena'?60:code==='phoenix'?36:12,coupon_percent:8,barrier_percent:60,tickers:['AIR.PA']});else props.config.products=props.config.products.filter(p=>p.template!==code)}
const money=n=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:4}).format(Number(n||0))
const economies=computed(()=>[{name:'Règle commune',economy:props.config.economy_common},...active.value.filter(p=>p.economy).map(p=>({name:names[p.key],economy:p.economy}))])
function lines(e){const pillars=e.funding[0]?.pillars||[];return pillars.map((_,i)=>e.funding.map(p=>`${25+p.month/Math.max(props.config.horizon_months,p.month)*550},${145-(p.pillars[i]?.[1]-e.minimum_bps)/Math.max(1,e.maximum_bps-e.minimum_bps)*120}`).join(' '))}
function numeric(event,object,field){const raw=event.target.value.replace(/[\s\u202f\u00a0]/g,'').replace(',','.');object[field]=raw===''?null:Number(raw)}
</script>
<template>
  <section class="panel configuration">
    <div class="heading"><div><h2>{{editing?'Modifier le scénario':'Préparer une campagne'}}</h2><p>Comptes et contreparties réutilisés · Bases de campagne isolées · Aucun démarrage à l’enregistrement</p></div><button class="btn-secondary" type="button" @click="emit('cancel')">Fermer</button></div>
    <nav class="config-tabs"><button v-for="[id,label] in [['scenario','Participants et produits'],['calendar','Calendrier RFQ'],['economy','Funding et marges'],['risk','Risque et couverture'],['execution','Exécution et coût']]" :key="id" type="button" :class="{selected:section===id}" @click="section=id">{{label}}</button></nav>
    <form @submit.prevent="emit('save')" @invalid.capture="showInvalid" @input.capture="validationError=''">
      <div class="config-scroll">
        <section v-show="section==='scenario'" data-config-section="scenario">
          <div class="fields"><label>Nom<input v-model="config.name" class="input" required maxlength="100"/></label><label>Date initiale<input v-model="config.start_date" @change="datesChanged" type="date" class="input" required/></label><label v-if="config.market_mode==='historical'">Date finale — arrêt strict<input v-model="config.end_date" @change="datesChanged" type="date" :max="today" class="input" required/></label><label>Durée du calendrier (mois)<HelpTip text="Rejeu historique : arrêt à la date finale, même avec des produits encore actifs. Ancien scénario synthétique : suivi jusqu’au dernier paiement."/><input v-model.number="config.horizon_months" :readonly="config.market_mode==='historical'" type="number" min="1" max="120" class="input" required/></label></div>
          <p v-if="config.market_mode==='historical'">Historiques existants · Cours renseigné prioritaire, sinon dernier cours connu à la date rejouée · Aucun cours futur généré.</p><div v-if="forecast?.market_sources?.length" class="table-shell"><table><thead><tr><th>Sous-jacent</th><th>Première date</th><th>Dernier cours conservé</th><th>Source des cours</th></tr></thead><tbody><tr v-for="m in forecast.market_sources" :key="m.ticker"><td>{{m.ticker}}</td><td>{{m.first_date||'—'}}</td><td>{{m.last_date||'Cours explicite requis'}}</td><td>{{m.price_basis==='RAW_CLOSE'?'Cours brut du cache':m.price_basis==='STORED_CLOSE'?'Close existant du cache':'Cours renseigné'}}</td></tr></tbody></table></div><h3>Rôles de chaque organisation <HelpTip text="Règles de cette campagne fictive seulement. Les droits natifs sont vérifiés au départ. Un répondant aux notes doit avoir une politique d’émetteur ; aucune réponse à sa propre RFQ."/></h3>
          <div class="table-shell"><table><thead><tr><th>Organisation</th><th>Active</th><th>Demande</th><th>Réponse</th><th>Émission de notes</th></tr></thead><tbody><tr v-for="p in config.participants" :key="p.key"><td>{{names[p.key]}}</td><td><input v-model="p.active" type="checkbox" :aria-label="names[p.key]+' active'"/></td><td><input v-model="p.request_rfq" type="checkbox" :disabled="!p.active" :aria-label="names[p.key]+' demande RFQ'"/></td><td><input v-model="p.respond_rfq" @change="roleChange(p)" type="checkbox" :disabled="!p.active" :aria-label="names[p.key]+' répond RFQ'"/></td><td><input v-model="p.issue_notes" type="checkbox" :disabled="!p.active" :aria-label="names[p.key]+' émet des notes'"/></td></tr></tbody></table></div>
          <h3>Produits à parcourir</h3><div class="checks"><label v-for="(label,code) in labels" :key="code"><input type="checkbox" :checked="config.products.some(p=>p.template===code)" @change="addProduct(code)"/>{{label}}</label></div>
          <article v-for="p in config.products" :key="p.template" class="product"><h4>{{labels[p.template]}}</h4><div class="fields"><label>Nominal (€)<input :value="money(p.nominal)" @change="numeric($event,p,'nominal')" inputmode="decimal" class="input"/></label><label>Maturité (mois)<input v-model.number="p.maturity_months" type="number" min="6" max="60" class="input"/></label><label>Coupon (%)<input v-model.number="p.coupon_percent" type="number" step="0.1" min="0" max="30" class="input"/></label><label>Barrière capital (%)<input v-model.number="p.barrier_percent" type="number" min="1" max="100" class="input"/></label><label>Sous-jacents<HelpTip text="Tickers séparés par des virgules. Historiques existants en cache. À chaque date, dernier cours connu ou cours explicitement renseigné."/><input :value="p.tickers.join(', ')" @change="p.tickers=$event.target.value.split(',').map(s=>s.trim()).filter(Boolean)" class="input"/></label><label v-for="ticker in p.tickers" :key="ticker">Cours initial explicite {{ticker}} (optionnel)<input :value="p.spot_overrides?.[ticker]??''" @change="spotChanged(p,ticker,$event.target.value)" type="number" step="any" min="0.000001" class="input" :aria-label="'Cours initial explicite '+ticker+' — '+labels[p.template]"/></label></div></article>
        </section>
        <section v-show="section==='calendar'" data-config-section="calendar"><h3>Nombre de RFQ décidé par mois <HelpTip text="Zéro signifie aucun nouveau besoin. Plusieurs RFQ restent des dossiers distincts. Les détails non renseignés sont répartis entre demandeurs et payoffs autorisés."/></h3>
          <p>Répartition automatique par défaut. Cliquez sur Détails pour fixer les parties et le payoff de chaque demande.</p>
          <div class="calendar"><article v-for="row in rows" :key="row.month"><label>Mois {{row.month}}<input :value="row.count" @input="count(row,$event.target.value)" type="number" min="0" max="1000" class="input" :aria-label="'RFQ du mois '+row.month"/></label><details v-if="row.count"><summary>Détails des {{row.count}} RFQ</summary><div v-for="i in Math.min(row.count,100)" :key="i" class="slot"><strong>#{{i}}</strong><label>Demandeur<select class="select" :value="row.slots[i-1]?.requester||''" @change="slot(row,i-1).requester=$event.target.value||null"><option value="">Automatique</option><option v-for="p in requesters" :key="p.key" :value="p.key">{{names[p.key]}}</option></select></label><label>Payoff<select class="select" :value="row.slots[i-1]?.template||''" @change="slot(row,i-1).template=$event.target.value||null"><option value="">Automatique</option><option v-for="p in config.products" :key="p.template" :value="p.template">{{labels[p.template]}}</option></select></label><div class="checks"><span>Destinataires (vide = tous les répondants)</span><label v-for="p in responders" :key="p.key"><input type="checkbox" :checked="row.slots[i-1]?.recipients?.includes(p.key)" @change="slot(row,i-1).recipients=$event.target.checked?[...slot(row,i-1).recipients,p.key]:slot(row,i-1).recipients.filter(k=>k!==p.key)"/>{{names[p.key]}}</label></div></div><p v-if="row.count>100">Au-delà de 100 détails, répartition automatique.</p></details></article></div>
        </section>
        <section v-show="section==='economy'" data-config-section="economy"><h3>Hypothèses synthétiques privées <HelpTip text="Courbe par maturité et évolution selon la date de campagne. Interpolation entre les dates, dernier niveau prolongé. Ces courbes n’entrent pas dans les termes échangés ni dans le drift des sous-jacents."/></h3>
          <div class="checks"><label v-for="p in active" :key="p.key"><input type="checkbox" :checked="!!p.economy" @change="override(p)"/>Personnaliser {{names[p.key]}}</label></div>
          <article v-for="entry in economies" :key="entry.name" class="product"><h4>{{entry.name}}</h4><div class="fields"><label>Funding minimum (bps/an)<input v-model.number="entry.economy.minimum_bps" type="number" class="input"/></label><label>Funding maximum (bps/an)<input v-model.number="entry.economy.maximum_bps" type="number" class="input"/></label><label>Variation max. par trimestre (bps)<input v-model.number="entry.economy.max_change_bps_per_quarter" type="number" min="1" class="input"/></label><label>Marge minimale (bps du nominal)<input v-model.number="entry.economy.margin_min_bps" type="number" class="input"/></label><label>Marge cible (bps du nominal)<input v-model.number="entry.economy.margin_target_bps" type="number" class="input"/></label><label>Marge maximale (bps du nominal)<input v-model.number="entry.economy.margin_max_bps" type="number" class="input"/></label></div>
            <svg class="funding-chart" viewBox="0 0 600 175" role="img" :aria-label="'Évolution des spreads de '+entry.name"><path d="M25 15 V145 H580" fill="none" stroke="#9aaec0"/><polyline v-for="(line,i) in lines(entry.economy)" :key="i" :points="line" fill="none" :stroke="['#194d76','#26937c','#b16a2a'][i%3]" stroke-width="2"/><text x="25" y="167" font-size="11">Mois 0</text><text x="515" y="167" font-size="11">Mois {{config.horizon_months}}</text></svg>
            <details v-for="(point,i) in entry.economy.funding" :key="i" :open="i===0"><summary>Courbe au mois {{point.month}}</summary><label>Mois du scénario<input v-model.number="point.month" type="number" min="0" class="input"/></label><OptimizerCurveInput v-model="point.pillars" label="Courbe de funding" rate-label="Spread (bps/an)" :minimum="entry.economy.minimum_bps" :maximum="entry.economy.maximum_bps"/><button v-if="i" type="button" class="btn-ghost" @click="entry.economy.funding.splice(i,1)">Retirer cette date</button></details><button type="button" class="btn-secondary" @click="addFunding(entry.economy)">Ajouter une date de funding</button>
          </article>
        </section>
        <section v-show="section==='risk'" data-config-section="risk"><div class="fields"><label>Surveillance quantitative<select v-model.number="config.cadences.risk_days" class="select"><option :value="15">Tous les 15 jours</option><option :value="30">Tous les mois</option></select></label><label>MtM complet<select v-model.number="config.cadences.mtm_months" class="select"><option :value="1">Mensuel</option><option :value="3">Trimestriel</option><option :value="6">Semestriel</option><option :value="12">Annuel</option></select></label><label>Chemins par pricing<input v-model.number="config.cadences.pricing_paths" type="number" min="500" max="20000" class="input"/></label></div><label class="check"><input v-model="config.cadences.mtm_on_events" type="checkbox"/>Ajouter un MtM aux événements contractuels</label><p>Concentrations et suivi du book sans nouveau pricing ; dates des calculs antérieurs visibles. Aucun commentaire IA de risque.</p>
          <div class="table-shell"><table><thead><tr><th>Organisation</th><th>Notes autorisées</th><th>Accords OTC fictifs</th><th>Limite émetteur (€)</th><th>Limite relation (€)</th></tr></thead><tbody><tr v-for="p in active" :key="p.key"><td>{{names[p.key]}}</td><td><input v-model="p.note_ready" type="checkbox"/></td><td><input v-model="p.otc_ready" type="checkbox"/></td><td><input :value="p.concentration_limit_eur==null?'':money(p.concentration_limit_eur)" @change="numeric($event,p,'concentration_limit_eur')" class="input" placeholder="Non définie"/></td><td><input :value="money(p.bilateral_limit_eur)" @change="numeric($event,p,'bilateral_limit_eur')" class="input"/></td></tr></tbody></table></div><p>Limite émetteur : signalement de concentration. Limite relation : contrôle natif avant booking. Les notes ne deviennent pas des OTC par présence d’un ISDA.</p>
          <h3>Recettes complémentaires, une seule fois</h3><div class="checks"><label v-for="(name,key) in coverageNames" :key="key"><input v-model="config.coverage_modules" type="checkbox" :value="key"/>{{name}}</label></div><p>AMC, FIFO, inscription et double validation hors couverture.</p>
        </section>
        <section v-show="section==='execution'" data-config-section="execution"><div class="fields"><label>Fournisseur<select v-model="config.provider" class="select"><option v-for="p in providers" :key="p.key" :value="p.key">{{p.label}}</option></select></label><label>Modèle<select v-model="config.model" class="select"><option v-for="m in models" :key="m.id" :value="m.id">{{m.label}}</option></select></label><label>Plafond API ($)<input v-model.number="config.max_ai_cost_usd" type="number" min="0.01" step="0.01" class="input"/></label><label>Appels IA maximum<input v-model.number="config.max_model_calls" type="number" min="1" class="input"/></label><label>Durée réelle maximum (minutes)<input v-model.number="config.max_wall_minutes" type="number" min="1" class="input"/></label><label>Actions maximum<input v-model.number="config.max_turns" type="number" min="10" max="5000" class="input"/></label><label>Délai d’une décision IA (secondes)<input v-model.number="config.timeout_seconds" type="number" min="10" max="180" class="input"/></label><label>Graine reproductible<input v-model.number="config.seed" type="number" min="0" class="input"/></label></div><p>Les agents sont sollicités sur les décisions commerciales prévues ; le suivi quantitatif est déterministe.</p><p>Un blocage arrête l’exécution et conserve les preuves. La reprise nécessite la qualification du blocage et une relecture native des books.</p></section>
      </div>
      <footer class="config-summary"><p v-if="error||validationError" role="alert" class="error">{{error||validationError}}</p><template v-if="forecast"><div class="estimate"><strong>{{money(forecast.rfqs)}} RFQ · {{money(forecast.quotes)}} cotations</strong><span>Pricings : jusqu’à {{money(forecast.pricings_high)}} · MtM : jusqu’à {{money(forecast.mtms_high)}} · IA : {{money(forecast.model_calls.central)}} appels estimés</span><strong>API : {{money(forecast.cost_usd.low)}} à {{money(forecast.cost_usd.high)}} $ · central {{money(forecast.cost_usd.central)}} $</strong><span>Durée indicative : {{forecast.duration_minutes.low}} à {{forecast.duration_minutes.high}} min · {{forecast.end_date?'arrêt au '+forecast.end_date:'suivi jusqu’au mois '+forecast.end_month}}</span></div><p v-for="w in forecast.warnings" :key="w" class="warning">{{w}}</p><details><summary>Hypothèses de l’estimation</summary><p v-for="a in forecast.assumptions" :key="a">{{a}}</p><small>{{forecast.pricing_source}}</small></details></template><p v-else>Vérification du scénario et estimation…</p><div class="actions"><button class="btn-primary" :disabled="busy||!forecast||!!error">{{editing?'Enregistrer les paramètres':'Créer la campagne'}}</button><span>Cette action ne lance aucune IA.</span></div></footer>
    </form>
  </section>
</template>
<style scoped>
.configuration{min-width:0;display:flex;flex-direction:column;height:100%;max-height:100%;overflow:hidden}.configuration form{flex:1;min-height:0;display:flex;flex-direction:column}.config-scroll{flex:1;overflow:auto;min-height:0;padding:4px 8px 12px 0}.config-tabs{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.config-tabs button{padding:8px;border:1px solid var(--border);border-radius:6px;font-size:12px}.selected{background:var(--surface2);color:var(--accent)}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.fields label,.product>label,.slot label{display:flex;flex-direction:column;gap:5px;font-size:12px}.checks,.check{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.checks label{display:flex;gap:6px;align-items:center;font-size:12px}.product{background:var(--surface2);padding:14px;border-radius:8px;margin:12px 0}h3{font-weight:650;margin:18px 0 10px}h4{font-weight:600;margin-bottom:12px}p{font-size:12px;line-height:1.6;color:var(--muted);margin:10px 0}.calendar{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}.calendar>article{border:1px solid var(--border);padding:12px;border-radius:6px}.calendar>article:has(details[open]){grid-column:1/-1}.slot{display:grid;grid-template-columns:40px 1fr 1fr;gap:10px;border-top:1px solid var(--border);padding:10px 0}.slot>.checks{grid-column:2/-1}.config-summary{flex-shrink:0;border-top:1px solid var(--border);padding-top:12px;max-height:36vh;overflow:auto}.estimate{display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:12px;font-variant-numeric:tabular-nums}.actions{display:flex;gap:12px;align-items:center;margin-top:12px}.actions span{font-size:12px}.warning{color:#9a5c0c}.error{color:#aa2732}.funding-chart{width:100%;max-height:175px;background:var(--surface);margin:10px 0}table{width:100%;font-size:12px}td,th{padding:8px;text-align:left;border-bottom:1px solid var(--border)}summary{cursor:pointer;font-size:12px;padding:8px 0}.table-shell{overflow:auto}@media(max-width:760px){.estimate{grid-template-columns:1fr}.configuration{max-height:100%}.slot{grid-template-columns:1fr}.slot>.checks{grid-column:1}}
</style>

<style scoped>.heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.heading p{margin-bottom:0}.config-tabs{flex-shrink:0}h2{font-weight:650;font-size:18px}</style>
